// Offsets in Codegen object matching layout generated by scpp
// Offset 0x60 (96):  LLVMContextRef context_
// Offset 0x68 (104): LLVMModuleRef module_
// Offset 0x70 (112): LLVMBuilderRef builder_
// Offset 0x78 (120): LLVMDIBuilderRef dibuilder_
static inline LLVMContextRef& codegen_context(void* self) {
    return *reinterpret_cast<LLVMContextRef*>(static_cast<char*>(self) + 96);
}
static inline LLVMModuleRef& codegen_module(void* self) {
    return *reinterpret_cast<LLVMModuleRef*>(static_cast<char*>(self) + 104);
}
static inline LLVMBuilderRef& codegen_builder(void* self) {
    return *reinterpret_cast<LLVMBuilderRef*>(static_cast<char*>(self) + 112);
}
static inline LLVMDIBuilderRef& codegen_dibuilder(void* self) {
    return *reinterpret_cast<LLVMDIBuilderRef*>(static_cast<char*>(self) + 120);
}

// In scpp, std::string is a class with a virtual destructor.
// Offset 0: vtable pointer
// Offset 8: void* handle_ (pointer to std::string)
static inline const char* scpp_string_to_cstr(const void* str_ptr) {
    if (!str_ptr) return "";
    void* handle = *reinterpret_cast<void* const*>(static_cast<const char*>(str_ptr) + 8);
    if (!handle) return "";
    return static_cast<const std::string*>(handle)->c_str();
}

