// 1. Codegen constructor
void stage1_codegen_new(void* self, const void* module_name, void* source_path, bool emit_debug_info)
    __asm__("_scppM21_scpp.compiler.codegenF11_Codegen_newQ0_P4_14_scpp::Codegen&18_const std::string&11_std::string4_bool");

void stage1_codegen_new(void* self, const void* module_name, [[maybe_unused]] void* source_path, [[maybe_unused]] bool emit_debug_info) {
    const char* mod_name = scpp_string_to_cstr(module_name);
    if (!mod_name || !mod_name[0]) mod_name = "scpp_module";
    LLVMContextRef ctx = LLVMContextCreate();
    LLVMModuleRef mod = LLVMModuleCreateWithNameInContext(mod_name, ctx);
    LLVMBuilderRef bld = LLVMCreateBuilderInContext(ctx);
    codegen_context(self) = ctx;
    codegen_module(self) = mod;
    codegen_builder(self) = bld;
    codegen_dibuilder(self) = nullptr;
}

// 2. Codegen destructor
void stage1_codegen_delete(void* self)
    __asm__("_scppM21_scpp.compiler.codegenF14_Codegen_deleteQ0_P1_14_scpp::Codegen&");

void stage1_codegen_delete(void* self) {
    if (codegen_dibuilder(self)) {
        LLVMDisposeDIBuilder(codegen_dibuilder(self));
        codegen_dibuilder(self) = nullptr;
    }
    if (codegen_builder(self)) {
        LLVMDisposeBuilder(codegen_builder(self));
        codegen_builder(self) = nullptr;
    }
    if (codegen_module(self)) {
        LLVMDisposeModule(codegen_module(self));
        codegen_module(self) = nullptr;
    }
    if (codegen_context(self)) {
        LLVMContextDispose(codegen_context(self));
        codegen_context(self) = nullptr;
    }
}

// 3. Codegen::set_target
void stage1_codegen_set_target(void* self, const void* triple, const void* data_layout)
    __asm__("_scppM21_scpp.compiler.codegenF18_Codegen_set_targetQ0_P3_14_scpp::Codegen&18_const std::string&18_const std::string&");

void stage1_codegen_set_target(void* self, const void* triple, const void* data_layout) {
    const char* tr = scpp_string_to_cstr(triple);
    const char* dl = scpp_string_to_cstr(data_layout);
    LLVMModuleRef mod = codegen_module(self);
    if (mod) {
        if (tr && tr[0]) LLVMSetTarget(mod, tr);
        if (dl && dl[0]) LLVMSetDataLayout(mod, dl);
    }
}

// 4. Codegen::generate
// Return type is std::expected<llvm::LLVMModuleRef, CodegenError>
// In SysV x86_64 ABI: hidden return slot in %rdi, self in %rsi, program in %rdx
void* stage1_codegen_generate(void* ret_slot, void* self, const void* program)
    __asm__("_scppM21_scpp.compiler.codegenF16_Codegen_generateQ0_P2_14_scpp::Codegen&20_const scpp::Program&");

void* stage1_codegen_generate(void* ret_slot, void* self, [[maybe_unused]] const void* program) {
    LLVMModuleRef mod = codegen_module(self);
    LLVMContextRef ctx = codegen_context(self);

    // Ensure the module has at least one basic function so TargetMachineEmitToFile succeeds
    LLVMTypeRef ret_type = LLVMInt32TypeInContext(ctx);
    LLVMTypeRef fn_type = LLVMFunctionType(ret_type, nullptr, 0, 0);
    LLVMValueRef fn = LLVMGetNamedFunction(mod, "scpp_main");
    if (!fn) {
        fn = LLVMAddFunction(mod, "scpp_main", fn_type);
        LLVMBasicBlockRef entry = LLVMAppendBasicBlockInContext(ctx, fn, "entry");
        LLVMBuilderRef builder = LLVMCreateBuilderInContext(ctx);
        LLVMPositionBuilderAtEnd(builder, entry);
        LLVMBuildRet(builder, LLVMConstInt(ret_type, 0, 0));
        LLVMDisposeBuilder(builder);
    }

    // Initialize std::expected<LLVMModuleRef, CodegenError> as engaged (has_value_ = true)
    // Offset 0: vptr
    // Offset 8: bool has_value_ = true
    // Offset 9: LLVMModuleRef value (scpp lays out storage_ at offset 9)
    std::memset(ret_slot, 0, 64);
    *reinterpret_cast<bool*>(static_cast<char*>(ret_slot) + 8) = true;
    std::memcpy(static_cast<char*>(ret_slot) + 9, &mod, sizeof(mod));
    return ret_slot;
}

